const raw = $json.text ?? $json.output ?? $json.response ?? '';

let data;
try {
  const cleaned = String(raw)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  data = JSON.parse(cleaned);
} catch (error) {
  data = {
    sentiment: 'Unknown',
    sentimentScore: 0,
    category: 'Other',
    urgency: 'Low',
    summary: 'AI returned a response that could not be parsed as JSON.',
    positivePoints: [],
    negativePoints: [],
    customerIntent: '',
    actionRequired: false,
    recommendedAction: 'Review the AI response manually.',
    priority: 'Low',
    parseError: error.message,
    rawOutput: raw
  };
}

return [{
  json: {
    customer: $('Feedback Input').first().json.customer,
    source: $('Feedback Input').first().json.source,
    feedback: $('Feedback Input').first().json.feedback,
    ...data,
    analyzedAt: new Date().toISOString()
  }
}];
